package ro.leo.visual;
import android.content.*;import android.database.Cursor;import android.net.Uri;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;
/** UTF-8 local LRC, bounded bytes/lines. Never downloads lyrics. */
final class LyricsData {
 static final class Line{final long time;final String text;Line(long t,String s){time=t;text=s;}}
 static final class Document{final ArrayList<Line> lines=new ArrayList<Line>();boolean timed;int active(long position){int lo=0,hi=lines.size()-1,result=-1;while(lo<=hi){int mid=(lo+hi)>>>1;if(lines.get(mid).time<=position){result=mid;lo=mid+1;}else hi=mid-1;}return result;}}
 static Document parse(String text)throws IOException{if(text.length()>262144)throw new IOException("Versuri peste 256 KiB");Document out=new Document();ArrayList<Line> plain=new ArrayList<Line>();Pattern time=Pattern.compile("\\[(\\d{1,3}):(\\d{2})(?:[.:](\\d{1,3}))?\\]");Matcher offset=Pattern.compile("\\[offset:([+-]?\\d{1,7})\\]",Pattern.CASE_INSENSITIVE).matcher(text);int shift=offset.find()?Integer.parseInt(offset.group(1)):0;int count=0;for(String row:text.replace("\ufeff","").split("\\r?\\n",-1)){if(++count>4000)throw new IOException("Prea multe rânduri");Matcher m=time.matcher(row);ArrayList<Long> times=new ArrayList<Long>();int end=0;while(m.find()){int sec=Integer.parseInt(m.group(2));if(sec>=60)continue;String frac=m.group(3);int ms=frac==null?0:Integer.parseInt((frac+"000").substring(0,3));times.add(Math.max(0,Integer.parseInt(m.group(1))*60000L+sec*1000L+ms+shift));end=m.end();if(times.size()>100)throw new IOException("Prea multe marcaje");}if(!times.isEmpty()){String value=row.substring(end).trim();for(long t:times){out.lines.add(new Line(t,value));if(out.lines.size()>2000)throw new IOException("Maximum 2000 rânduri");}}else if(!row.trim().isEmpty()&&!row.trim().matches("\\[[a-zA-Z]+:.*")){plain.add(new Line(-1,row.trim()));if(plain.size()>2000)throw new IOException("Maximum 2000 rânduri");}}out.timed=!out.lines.isEmpty();if(out.timed)Collections.sort(out.lines,new Comparator<Line>(){public int compare(Line a,Line b){return Long.compare(a.time,b.time);}});else out.lines.addAll(plain);return out;}
 static boolean allowed(Context c,File f)throws IOException{if(!f.getCanonicalFile().equals(f.getAbsoluteFile()))return false;for(File root:LeoFileProvider.roots(c).values())if(LeoFileProvider.inside(root,f))return true;return false;}
 static File audioFile(Context c,String source){try{Uri u=Uri.parse(source);File file=null;if("file".equals(u.getScheme()))file=new File(u.getPath());else if("content".equals(u.getScheme())&&"media".equals(u.getAuthority()))try(Cursor row=c.getContentResolver().query(u,new String[]{"_data"},null,null,null)){if(row!=null&&row.moveToFirst()&&row.getString(0)!=null)file=new File(row.getString(0));}return file!=null&&allowed(c,file)?file:null;}catch(Exception e){return null;}}
 static File sidecar(Context c,String source){File audio=audioFile(c,source);if(audio==null)return null;String name=audio.getName();int dot=name.lastIndexOf('.');File lrc=new File(audio.getParentFile(),(dot>0?name.substring(0,dot):name)+".lrc");try{return allowed(c,lrc)&&lrc.isFile()?lrc:null;}catch(IOException e){return null;}}
 static Document read(Context c,File file)throws Exception{if(!allowed(c,file)||!file.getName().toLowerCase(Locale.ROOT).endsWith(".lrc"))throw new IOException("Alege un fișier LRC local");return parse(new String(BackupEngine.bytes(file,262144),StandardCharsets.UTF_8));}
 static ArrayList<File> files(Context c,String source){ArrayList<File> out=new ArrayList<File>();ArrayList<File> roots=new ArrayList<File>();File audio=audioFile(c,source);if(audio!=null)roots.add(audio.getParentFile());roots.add(new File(c.getFilesDir(),"documents/Lyrics"));for(File base:LeoFileProvider.roots(c).values())roots.add(new File(base,"Documents/LeoLyrics"));HashSet<String> seen=new HashSet<String>();for(File dir:roots){File[] list=dir.listFiles();if(list==null)continue;int count=0;for(File f:list){if(++count>200)break;try{if(f.isFile()&&f.getName().toLowerCase(Locale.ROOT).endsWith(".lrc")&&allowed(c,f)&&seen.add(f.getCanonicalPath()))out.add(f);}catch(IOException ignored){}if(out.size()>=200)break;}}Collections.sort(out,new Comparator<File>(){public int compare(File a,File b){return a.getName().compareToIgnoreCase(b.getName());}});return out;}
}
